const root=document.createElement('section');root.id='aApp';document.querySelector('.mainwrap').appendChild(root);
const opts=Object.entries(T.FAULTS).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');
root.innerHTML=`<div class="a-runbar"><div class="a-scenario"><label for="aScenario">Jarayon ssenariysi</label><select id="aScenario">${opts}</select></div><button id="amPlay">▶ Ishga tushirish</button><button id="amStop" class="asec" title="Hisoblashni to‘xtatadi; texnologik ESD emas">■ STOP</button><button id="amStep" class="asec" title="Pauzada 0.1 s hisoblash">+0.1 s</button><button id="amReset" class="asec">↺ Boshlang‘ich holat</button><div><label for="aSpeed">Vaqt tezligi</label><select id="aSpeed"><option value="1">1×</option><option value="2">2×</option><option value="5" selected>5×</option><option value="10">10×</option><option value="20">20×</option><option value="60">60×</option></select></div><div class="a-clock" id="aClock">00:00.0</div></div>
<div class="a-replaybar" id="aReplayBar"><span id="aReplayInfo"></span><button id="aLive" class="asec">Jonli modelga qaytish</button></div>
<div class="a-title"><div><div class="a-kicker">GP1701 / DA-1701 / FA-1702</div><h1 id="aViewTitle">Umumiy ko‘rinish</h1><p id="aViewDesc"></p></div><span id="aStatus" class="a-status">NORMAL</span></div>
<div class="a-panel" data-ap="overview"><div id="aMetrics" class="a-metrics"></div><div id="aEquipment" class="a-equipgrid"></div><div class="a-maincols"><div class="a-card"><div class="a-toolbar"><b style="font-size:12px">Jarayon mnemosxemasi</b><span class="spacer"></span><button data-go="mimic" class="asec">Kengaytirish ↗</button><button data-go="3d">3D ko‘rinish ↗</button></div><div id="aOverviewMimic" class="a-mimic-canvas"></div></div><div><div class="a-card a-pad"><h2>Jarayon diagnostikasi</h2><div id="aOverviewDiag" class="a-diagnostics"></div></div><div class="a-card a-pad" style="margin-top:12px"><h2>Oqimlar balansi</h2><div id="aBalance" class="a-flows"></div><p class="a-muted">%Qref — har bir oqimning o‘z referens qiymatiga nisbati.</p></div><div class="a-card a-pad" style="margin-top:12px"><h2>So‘nggi hodisalar</h2><div id="aRecent"></div></div></div></div></div>
<div class="a-panel" data-ap="mimic"><div class="a-card" id="aMimicCard"><div class="a-toolbar"><button id="aZoomOut" class="asec" aria-label="Kichraytirish">−</button><span id="aZoomValue" class="a-muted">100%</span><button id="aZoomIn" class="asec" aria-label="Kattalashtirish">+</button><button id="aFit" class="asec">Joylashtirish</button><span class="spacer"></span><button id="aEditTags" class="asec">Teglarni joylashtirish</button><button id="aUndoTags" class="asec" disabled>↶ Bekor qilish</button><button id="aSaveLayout" class="asec">Joylashuvni saqlash</button><button data-full="aMimicCard" class="asec">⛶ To‘liq ekran</button></div><div id="aMimic" class="a-mimic-canvas"></div><div class="a-under"><span id="aMimicHint">Apparat yoki klapanni bosing. G‘ildirak bilan masshtab, bo‘sh joyni tortib siljitish.</span><span>O‘lchovlar: simulyatsiya</span></div></div></div>
<div class="a-panel" data-ap="3d"><div class="a-card" id="aSceneCard"><div class="a-toolbar"><button data-camera="complex" class="asec">Majmua (SGCC)</button><button data-camera="all" class="asec on">Amin bloki</button><button data-camera="tower" class="asec">DA-1701</button><button data-camera="sep" class="asec">FA-1702</button><button data-camera="cool" class="asec">EA-1706 A/B/C</button><button data-camera="ethylene" class="asec">Etilen</button><button data-camera="tank" class="asec">Rezervuarlar</button><button data-camera="top" class="asec">Bosh reja</button><span class="spacer"></span><button id="aCut" class="asec">Ichki kesim</button><button id="aFlows" class="asec on">Oqimlar</button><button id="aLabels" class="asec on">Teglar</button><button id="aOrbit" class="asec">Aylanish</button><select id="aQuality" aria-label="3D sifati"><option value="high">Yuqori sifat</option><option value="low">Yengil rejim</option></select><button id="aShot" class="asec">PNG</button><button data-full="aSceneCard" class="asec">⛶</button></div><div class="a-scene" id="aScene"><canvas id="amCanvas" aria-label="DA-1701 texnologik qurilmasining interaktiv 3D ko‘rinishi"></canvas><div class="a3-error" hidden></div><div class="a-scene-badge" id="aSceneBadge">FAZOVIY MODEL · apparatni bosing</div><div id="aSceneReadout" class="a-scene-readout"></div></div><div class="a-under"><div class="a-legend"><span><i style="background:#559dc6"></i>Gaz</span><span><i style="background:#43a995"></i>To‘yinmagan amin</span><span><i style="background:#c7a051"></i>To‘yingan amin</span><span><i style="background:#9385b4"></i>Kondensat / yuvish</span></div><span>Ichki tuzilma va zarrachalar sxematik; oqim va sath modeldan olinadi.</span></div></div></div>
<div class="a-panel" data-ap="trends"><div class="a-toolbar a-card" style="margin-bottom:12px"><b style="font-size:12px">Jarayon arxivi</b><span class="a-muted" id="aHistoryCount"></span><span class="spacer"></span><button id="aExportCsv" class="asec">CSV eksport</button><button data-go="review" class="asec">Qayta ko‘rish</button></div><div class="a-charts" id="aCharts"></div></div>
<div class="a-panel" data-ap="ai"><div class="a-maincols"><div class="a-card a-pad"><h2>Balans va signal sifati tahlili</h2><div class="a-diagnostics" id="aDiag"></div><p class="a-muted">Tahlil deterministik qoidalar va oqim balansiga asoslanadi. Bu bo‘lim o‘qitilgan AI modeli yoki haqiqiy PLC himoyasi sifatida ko‘rsatilmaydi.</p></div><div class="a-card a-pad"><h2>Faol o‘quv ogohlantirishlari</h2><div id="aActive"></div><button id="aAck" class="asec">Tasdiqlash (ACK)</button></div></div></div>
<div class="a-panel" data-ap="review"><div class="a-card a-pad"><h2>Yozilgan jarayonni qayta ko‘rish</h2><div class="a-replay-controls"><button id="aReplayPlay">▶ Arxivni o‘ynatish</button><input id="aScrub" type="range" min="0" max="0" value="0" aria-label="Arxiv vaqti"><span id="aScrubLabel" class="a-muted"></span><button id="aReviewMimic" class="asec">Mnemosxemada</button><button id="aReview3d" class="asec">3D’da</button><button id="aReport" class="asec">Hisobot</button></div><p class="a-muted">Vaqt chizig‘i yoki hodisani tanlang — mnemosxema va 3D o‘sha arxiv holatini ko‘rsatadi.</p><div id="aReviewMetrics" class="a-metrics"></div><div class="tw"><table class="a-table"><thead><tr><th>Vaqt</th><th>Holat</th><th>Hodisa</th><th>Ko‘rish</th></tr></thead><tbody id="aReviewRows"></tbody></table></div></div></div>
<div class="a-panel" data-ap="journal"><div class="a-card"><div class="a-toolbar"><select id="aEventFilter" aria-label="Hodisalar filtri"><option value="all">Barcha hodisalar</option><option value="alarm">Ogohlantirishlar</option><option value="unack">Tasdiqlanmagan</option></select><span class="spacer"></span><button id="aAckAll" class="asec">Barchasini tasdiqlash</button><button id="aEventExport" class="asec">Jurnal CSV</button></div><div class="tw"><table class="a-table"><thead><tr><th>t, s</th><th>Daraja</th><th>Teg / kod</th><th>Hodisa</th><th>ACK</th></tr></thead><tbody id="aEvents"></tbody></table></div></div></div>
<div class="a-panel" data-ap="batch"><div class="a-card a-pad"><h2>Ssenariylarni bir xil sharoitda solishtirish</h2><p class="a-muted">Har bir ssenariy 300 model soniya davomida alohida nusxada ishlaydi. Joriy jarayon holatiga ta’sir qilmaydi.</p><button id="aBatch">Barcha ssenariylarni sinash</button><span id="aBatchStatus" class="a-muted"></span><div class="tw"><table class="a-table"><thead><tr><th>Ssenariy</th><th>DA sath, %</th><th>KO sath, %</th><th>TI17007, °C</th><th>Birinchi ogohlantirish</th><th>Signal sifati</th></tr></thead><tbody id="aBatchRows"></tbody></table></div></div></div>
<div class="a-panel" data-ap="data"><div class="a-maincols"><div class="a-card a-pad"><h2>Jarayon CSV arxivini ochish</h2><p class="a-muted">Shu dastur eksport qilgan CSV’ni import qilib, mnemosxema va 3D’da qayta ko‘ring. Import yozuvlari jonli model hisobini almashtirmaydi.</p><input id="aCsvImport" type="file" accept=".csv,text/csv"><div id="aImportStatus" class="a-import-status" role="status"></div><button id="aTemplateCsv" class="asec">Joriy arxivni yuklab olish</button><p class="a-muted">Format: t, g, lean, wash, rich, drain, water, L, K, W, Ti, To, Tr, dp, press, quality_L va barcha valve_* ustunlari majburiy. Buyruq/holat, AUTO/SP, fizik L va alarm holati yangi eksportda alohida saqlanadi. BAD sath alohida quality_L ustuni bilan saqlanadi.</p><h2 style="margin-top:20px">Manbalardan olingan ma’lumot</h2><p class="a-muted">P&ID: DA-1701 absorber, FA-1702 separator, kontakt va yuvish bo‘limlari hamda ulanishlar. GP1701 ekrani: EA-1706 A/B/C va signal teglarining boshlang‘ich referenslari.</p></div><div class="a-card a-pad"><h2>Aniqlik chegarasi</h2><p class="a-muted">3D geometrik o‘lchamlari va maydon joylashuvi taxminiy. Sath boshqaruvi, ogohlantirish chegaralari va vaqt doimiylari — o‘quv parametrlari. Sarf fizik birligi va PI17012 kalibrovkasi tasdiqlanmagan: kPa model farazi, 100 kPa = 1 bar. Kimyoviy tozalash modeli DCS ekranidagi nominal nuqtaga kalibrlangan; SIS C&E — P&ID asosidagi o‘quv farazi.</p><p class="a-muted">Manba ekranidagi NaN hamda −1.2% nominal sath deb qabul qilinmagan. FCI sarf birliklari aniqlanmagani uchun %Qref ishlatiladi.</p></div></div><div class="a-card a-pad" style="margin-top:13px"><h2>P&ID / HMI muvofiqlik registri</h2><p class="a-muted">MOS — yo‘nalish tasdiqlangan; QISMAN — fizik model yoki hujjat yetishmaydi; MODELLANMAGAN — faqat manbada va registrda saqlangan.</p><div class="tw"><table class="a-table"><thead><tr><th>TAG / element</th><th>Manba</th><th>Vazifa</th><th>Dastur</th><th>Holat / cheklov</th></tr></thead><tbody><tr><td>DA-1701</td><td>P&amp;ID</td><td>Kislotali gaz absorberi, kontakt va yuqori yuvish bo‘limi</td><td>2D/3D va L/W balanslari mavjud</td><td>QISMAN — geometriya, hajm, tarelka o‘lchamlari tasdiqlanmagan</td></tr><tr><td>FA-1702</td><td>P&amp;ID</td><td>Tabiiy gaz kondensatini ajratuvchi KO drum</td><td>2D/3D, K sathi va drenaj modeli</td><td>QISMAN — kondensat hosil bo‘lishi soddalashtirilgan</td></tr><tr><td>EA-1706A / B / C</td><td>GP1701 HMI</td><td>Uchta parallel gaz sovitgichi</td><td>Uch tarmoq va umumiy harorat modeli</td><td>QISMAN — ushbu P&amp;ID varag‘ida batafsil sovitgichlar yo‘q</td></tr><tr><td>PV17001A / B / C</td><td>GP1701 HMI</td><td>Gaz tarmoq klapanlari</td><td>Mustaqil buyruq va inersion holat</td><td>QISMAN — Cv, fail position va signal diapazonlari yo‘q</td></tr><tr><td>FCI17001</td><td>GP1701 HMI; P&amp;IDda boshqa varaqqa ulanish</td><td>Gaz sarfi va chiqish klapani</td><td>Bir xil gaz oqimi, chiqish sig‘imi bilan cheklangan</td><td>QISMAN — gaz siqiluvchanligi va quvur hajmi hisoblanmaydi</td></tr><tr><td>FCI17002 / EC-1701</td><td>GP1701 HMI; P&amp;ID</td><td>To‘yinmagan amin kirishi</td><td>Kontakt bo‘limiga kiradi; sarf topshirig‘i</td><td>QISMAN — qo‘shimcha klapan TAG o‘ylab topilmagan</td></tr><tr><td>FT17003 / FC17003; HMI FCI17003</td><td>P&amp;ID va GP1701 HMI</td><td>EA-1131 dan yuvish kondensati</td><td>Yuqori bo‘limga kirish, FCI17003 alias</td><td>QISMAN — asbob va HMI yozuvi farqi saqlanadi</td></tr><tr><td>LC17001</td><td>P&amp;ID va GP1701 HMI</td><td>FA-1702 drenaj sath konturi</td><td>AUTO/MANUAL, % sath, drenaj</td><td>QISMAN — P-regulyator o‘quv modeli, zavod PID emas</td></tr><tr><td>LC17002</td><td>P&amp;ID va GP1701 HMI</td><td>Yuvish bo‘limi sath konturi</td><td>Mustaqil W inventari va yuvish chiqishi</td><td>QISMAN — geometrik va PID sozlamalar yo‘q</td></tr><tr><td>LC17003</td><td>P&amp;ID va GP1701 HMI</td><td>Absorber pastki sath konturi</td><td>L inventari, BAD signal va buyruqni ushlash</td><td>QISMAN — BAD holatidagi ushlash o‘quv strategiyasi</td></tr><tr><td>TI17005 / TI17008</td><td>P&amp;ID va GP1701 HMI</td><td>Gaz chiqishi / to‘yingan amin harorati</td><td>56.5 / 60.6 °C boshlang‘ich referens, dinamik model</td><td>QISMAN — energiya balansi kalibrlanmagan</td></tr><tr><td>TC17001; HMI TI17007</td><td>P&amp;ID va GP1701 HMI</td><td>Sovitish konturi / gaz kirish harorati</td><td>Sovitish suvi pasayishi haroratga ta’sir qiladi</td><td>QISMAN — sovitish chiqishi boshlang‘ich 65% o‘quv qiymati; HMI 105% nominal deb olinmagan</td></tr><tr><td>PDI17009 / PDI17010 / PDI17010A</td><td>P&amp;ID / GP1701 HMI</td><td>P&amp;IDda PDI17009; HMIda PDI17010 va PDI17010A</td><td>PDI17010 o‘quv modeli mavjud</td><td>FARQ — teglar o‘zaro tenglashtirilmagan; PDI17009/10A alohida dinamik model yo‘q</td></tr><tr><td>PI17012</td><td>GP1701 HMI</td><td>Tabiiy gaz kirish bosimi</td><td>3718 referens; modelda kPa deb faraz qilingan</td><td>QISMAN — HMI rasmida birlik ko‘rinmaydi; bar konversiyasi 100 kPa = 1 bar</td></tr><tr><td>PSV-1702 guruhi, 5 dona</td><td>P&amp;ID</td><td>Wet flare kollektoriga mexanik bosim himoyasi; 4370 kPag yozuvi</td><td>3Dda sxematik kollektor; registrda mavjud</td><td>MODELLANMAGAN — PSV sarf xarakteristikasi, suffikslar va key-interlock konfiguratsiyasi tasdiqlanishi kerak</td></tr><tr><td>ZSL17001 / ZL17001</td><td>P&amp;ID</td><td>Separator drenaj klapani yopiq holat signali</td><td>Registrda qayd etildi</td><td>MODELLANMAGAN — holat datchigi diagnostikasi va mantiq yo‘q</td></tr><tr><td>ZSF17003 / ZIF17003 (yozuvni tekshirish kerak)</td><td>P&amp;ID</td><td>Kondensat klapani yonidagi holat signallari</td><td>Registrda tasdiqlash talabi bilan qayd etildi</td><td>NOANIQ — skan va legend asosida tag turi aniqlashtiriladi</td></tr><tr><td>PG17051 / LG17051</td><td>P&amp;ID</td><td>FA-1702 mahalliy bosim va sath asboblari</td><td>Registrda qayd etildi; K o‘lchovi mavjud</td><td>MODELLANMAGAN — alohida asbob xatosi yo‘q</td></tr><tr><td>PG17052 / LG17052 / LG17053 / LG17054</td><td>P&amp;ID</td><td>Absorber mahalliy ko‘rsatkichlari, interfeys sathi</td><td>Registrda qayd etildi</td><td>MODELLANMAGAN — ikki suyuqlik interfeysi alohida hisoblanmaydi</td></tr><tr><td>S1701 / S1702 / SC1705</td><td>P&amp;ID</td><td>Namuna olish ulanishlari (note 17)</td><td>Manba rasmida va registrda saqlangan</td><td>MODELLANMAGAN — ularni nasos yoki ESD deb qabul qilinmagan</td></tr><tr><td>EA-1821</td><td>P&amp;ID ulanishi / GP1701 HMI</td><td>Tozalangan gaz chiqish yo‘nalishi</td><td>2D/3D chiqish chegarasi</td><td>MOS — tashqi apparat ichki modeli bu varaq doirasida yo‘q</td></tr><tr><td>FA-1705</td><td>P&amp;ID ulanishi / GP1701 HMI</td><td>To‘yingan amin chiqish yo‘nalishi</td><td>2D/3D chiqish chegarasi</td><td>MOS — tashqi apparat modeli yo‘q</td></tr><tr><td>FA-6908</td><td>GP1701 HMI</td><td>Separator kondensati chiqish yo‘nalishi</td><td>2D/3D chiqish chegarasi</td><td>QISMAN — ushbu P&amp;IDda tashqi marshrut qo‘shimcha varaq talab qiladi</td></tr><tr><td>Qo‘l klapanlari, bypass, vent va drenajlar</td><td>P&amp;ID</td><td>Texnologik xizmat va armatura</td><td>Original P&amp;ID dastur ichida mavjud</td><td>MODELLANMAGAN — barcha kichik armaturalar mustaqil boshqarilmaydi</td></tr><tr><td>Nasos / elektrodvigatel</td><td>Berilgan P&amp;ID varag‘i va GP1701 HMI</td><td>Ushbu chegarada nasos/motor TAG tasdiqlanmadi</td><td>Qo‘shimcha soxta uskuna kiritilmadi</td><td>NOT TESTED — qo‘shni varaqlar va uskuna ro‘yxati talab qilinadi</td></tr><tr><td>H/HH/L/LL, SIS / ESD</td><td>P&amp;ID: LC17003 ZSL/ZSC, LC17001 ZSL, PSV-1702A…E, 16-izoh</td><td>DCS ogohlantirishlari va SIS trip nuqtalari alohida</td><td>6 SIF: 2oo3 / 1oo2, XV fail-close, latch, RESET, bypass (SIS / ESD bo‘limi)</td><td>QISMAN — C&amp;E o‘quv farazi; zavod hujjati bilan tasdiqlanishi kerak</td></tr></tbody></table></div></div><div class="a-card a-ref" style="margin-top:13px"><details><summary>145.TIF — original P&ID</summary><img src="${window.AMINE_REFS.pid}" alt="DA-1701 va FA-1702 P&ID"></details><details><summary>1451.jpg — original GP1701 operator ekrani</summary><img src="${window.AMINE_REFS.hmi}" alt="Original GP1701 ekrani"></details></div></div>
<div class="a-panel a-model" data-ap="math"><div class="a-card a-pad"><h2>Hisoblash modeli — ko‘rinishlar uchun yagona holat</h2><p>Model 0.1 s dan katta bo‘lmagan ichki qadam bilan ishlaydi. 2D, 3D, trendlar, diagnostika va arxiv aynan bir holat nusxasini o‘qiydi. Sarflar o‘z referens oqimiga nisbatan normalizatsiya qilingan.</p><code>Gaz sarfi = min(uchta kirish tarmog‘i yig‘indisi, chiqish klapani sig‘imi)<br>Sath o‘zgarishi = k × (kirish − chiqish) × dt<br>Chiqish sarfi = Qref × (klapan / nominal) × √(sath / nominal sath)<br>Klapan yuritmasi = birinchi tartibli yaqinlashish, τ = 1.4 s</code><p>Suyuq inventar 0–100% oralig‘ida saqlanadi. Bo‘sh idishdan chiqariladigan sarf mavjud inventar va kirish bilan cheklanadi. 100% dan yuqori hisobiy inventar toshish indikatori sifatida qayd qilinadi.</p><h2>Regulyator va signal sifati</h2><p>AUTO — nominal klapan holati va sath xatosiga proporsional tuzatish. Engineering bo‘limida PID (anti-windup va bumpless transfer) tajribasi yoqiladi. Bu sozlangan sanoat PID konturining nusxasi emas. MANUAL’da operator buyrug‘i ishlaydi. LC17003 signali BAD bo‘lsa, AUTO oxirgi buyruqni ushlab turadi, o‘lchov NaN bo‘ladi va sath prognozi to‘xtaydi.</p><h2>O‘quv ogohlantirishlari</h2><p>Sath chegaralari sozlamalarda ko‘rsatilgan; tiklanish uchun 2 foiz punkt gisterezis bor. Ogohlantirishni ACK qilish texnologik sababni yo‘qotmaydi. Avtomatik himoya — alohida SIS (mustaqil uzatgichlar, XV klapanlar).</p><h2>Oqim balansidan prognoz</h2><code>Chegaragacha taxminiy vaqt = (chegara − joriy sath) / joriy sath tezligi</code><p>Prognoz faqat signal sifatli va balans o‘zgarmasligi farazida beriladi. AI erta ogohlantirish (Isolation Forest, sabab tashxisi va raqamli egizak qoldiqlari) “Diagnostika” bo‘limida.</p></div></div>
<div class="a-panel" data-ap="settings"><div class="a-settinggrid" id="aLoopSettings"></div><div class="a-maincols" style="margin-top:13px"><div class="a-card a-pad"><h2>Klapanlar / sarf topshiriqlari</h2><div id="aValveSettings"></div></div><div class="a-card a-pad"><h2>O‘quv diagnostika chegaralari</h2><p class="a-muted">Bu qiymatlar haqiqiy texnologik setpoint sifatida tasdiqlanmagan.</p><label for="aLowLow">Low-Low sath, % · o‘quv</label><input id="aLowLow" type="number" min="0" max="44" value="5"><label for="aHighHigh">High-High sath, % · o‘quv</label><input id="aHighHigh" type="number" min="56" max="100" value="95"><label for="aLow">Past sath, %</label><input id="aLow" type="number" min="0" max="45" value="10"><label for="aHigh">Yuqori sath, %</label><input id="aHigh" type="number" min="55" max="100" value="85"><label for="aTemp">TI17007 yuqori harorat, °C</label><input id="aTemp" type="number" min="35" max="150" value="70"><label for="aRatio">Minimal nisbiy amin/gaz</label><input id="aRatio" type="number" min="0.1" max="1.5" step=".05" value=".65"><button id="aSaveSettings" style="margin-top:12px">Qo‘llash</button><p id="aSettingsStatus" class="a-muted" role="status"></p><h2>SIS / ESD</h2><p class="a-muted">Blokirovkalar “SIS / ESD blokirovka” bo‘limida: 6 ta SIF (2oo3 / 1oo2 ovoz berish), XV fail-close klapanlar, latch, RESET va bypass. DCS H/HH/L/LL — operator ogohlantirishlari; SIS mustaqil uzatgichlar bilan ishlaydi. STOP faqat hisoblashni muzlatadi, ESD emas.</p></div></div></div>
<div class="a-footer">P&ID asosidagi o‘quv modeli · Ishlab chiqarish tizimiga ulanmagan · Fayl internet va hisobga kirishsiz ishlaydi</div>
<aside class="a-drawer" id="aDrawer" aria-label="Apparat tafsilotlari"><div class="a-drawer-head"><h2 id="aDrawerTitle"></h2><button id="aDrawerClose" class="asec" aria-label="Tafsilotlarni yopish">×</button></div><div id="aDrawerBody" class="a-pad"></div></aside>`;
const descriptions={overview:'Jarayon holati, asosiy apparatlar va oqimlar balansi.',sis:'Xavfsizlik funksiyalari (SIF): sabab–oqibat matritsasi, 2oo3 / 1oo2 ovoz berish, XV klapanlar, bypass va RESET.',mimic:'Gaz oqimlari, kontakt va yuvish bo‘limlari — P&ID / GP1701 asosida.','3d':'Hajmli apparatlar, quvurlar va xizmat maydonchalari. Sichqoncha bilan aylantiring, apparatni bosing.',trends:'Birliklari ajratilgan trendlar va signallarning sifat holati.',ai:'Oqim balansi, signal sifati va kuzatilgan jarayon o‘zgarishlari.',review:'Hodisani tanlang va o‘sha paytdagi jarayonni ko‘ring.',journal:'O‘quv ogohlantirishlari, operator buyruqlari va tiklanishlar.',batch:'Bir xil model sharoitida deterministik taqqoslash.',data:'CSV arxivi, original P&ID va operator mnemosxemasi.',math:'Hisoblash bog‘lanishlari, farazlar va qo‘llanish chegaralari.',settings:'Har bir sath konturi uchun AUTO / MANUAL va o‘quv mezonlari.'};
const chartDefs=[{id:'pidrich',title:'LC17003 — PV / SP / OP',unit:'%',keys:['L','sp_rich','v_rich'],labels:['PV','SP','OP'],colors:['#309d9e','#ac83cf','#c69b43']},{id:'flow',title:'Gaz va amin sarflari',unit:'%Qref',keys:['g','lean','rich'],labels:['Gaz','Amin kirishi','Amin chiqishi'],colors:['#399ec7','#31ac91','#c69b43']},{id:'level',title:'Sathlar',unit:'%',keys:['L','K','W'],labels:['DA-1701','FA-1702','Yuvish'],colors:['#309d9e','#ad83cf','#ce9b47'],limits:true},{id:'temp',title:'Haroratlar',unit:'°C',keys:['Ti','To','Tr'],labels:['TI17007','TI17005','TI17006'],colors:['#3b9ac8','#c97779','#be984b']},{id:'pressure',title:'PI17012 — kirish bosimi',unit:'kPa',keys:['press'],labels:['PI17012'],colors:['#598bd2']},{id:'dp',title:'PDI17010 — bosim farqi',unit:'ref. birlik',keys:['dp'],labels:['PDI17010'],colors:['#9b77c5']},{id:'quality',title:'AI17001 — tozalangan gazda CO₂',unit:'ppmv',keys:['ai','aiExp'],labels:['AI17001','Raqamli egizak'],colors:['#d0675f','#7b8fa3'],spec:'co2'},{id:'h2s',title:'H₂S qoldig‘i (hisobiy)',unit:'ppmv',keys:['h2s'],labels:['H₂S'],colors:['#c9a13b'],spec:'h2s'},{id:'alpha',title:'To‘yingan amin yuklanishi (hisobiy)',unit:'mol/mol',keys:['alpha'],labels:['α'],colors:['#45a98f'],spec:'alpha'},{id:'valve',title:'Sath klapanlari holati',unit:'%',keys:['v_rich','v_drain','v_water'],labels:['LC17003','LC17001','LC17002'],colors:['#c69b43','#9c83c7','#3b9cac']}];
$('aCharts').innerHTML=chartDefs.map(c=>`<div class="a-card a-chart"><h2>${c.title} <span class="a-muted">· ${c.unit}</span></h2><div class="a-chart-legend">${c.labels.map((l,i)=>`<span><i style="display:inline-block;width:12px;height:2px;background:${c.colors[i]};vertical-align:middle;margin-right:5px"></i>${l}</span>`).join('')}</div><canvas id="chart-${c.id}" aria-label="${c.title}"></canvas><div class="a-tip" id="tip-${c.id}"></div></div>`).join('');
$('aLoopSettings').innerHTML=[['rich','LC17003','DA-1701 sathi','L'],['drain','LC17001','FA-1702 sathi','K'],['water','LC17002','Yuvish sathi','W']].map(([k,t,title,field])=>`<div class="a-card a-pad"><h2>${t} · ${title}</h2><div class="a-data-row"><span>PV</span><b id="loop-pv-${k}"></b></div><label for="loop-mode-${k}">Rejim</label><select id="loop-mode-${k}" data-control-mode="${k}"><option value="auto">AUTO</option><option value="manual">MANUAL</option></select><label for="loop-sp-${k}">Sath topshirig‘i, %</label><input id="loop-sp-${k}" type="number" min="5" max="90" step=".1" value="${model.sp[k]}"><p class="a-muted" id="loop-output-${k}"></p></div>`).join('');
$('aValveSettings').innerHTML=V.map(v=>`<div class="a-sliderrow"><div class="a-data-row"><span>${v.tag} · ${v.title}</span><b id="setting-v-${v.id}"></b></div><input type="range" id="av-${v.id}" min="0" max="100" value="${v.nom}" aria-label="${v.tag}"></div>`).join('');
const time=t=>`${Math.floor(t/60).toString().padStart(2,'0')}:${(t%60).toFixed(1).padStart(4,'0')}`;function snapshot(){return replay>=0&&history[replay]?history[replay]:model.snapshot()}
function saveFile(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function setNavText(amine){document.querySelectorAll('[data-view]').forEach(el=>{const n=[...el.childNodes].find(n=>n.nodeType===3&&n.textContent.trim());if(!n)return;if(!el.dataset.oldText)el.dataset.oldText=n.textContent;n.textContent=amine?' '+(names[el.dataset.view]||el.dataset.view):el.dataset.oldText})}
function navigate(v){if(!(v in names))v='overview';view=v;root.querySelectorAll('[data-ap]').forEach(p=>p.classList.toggle('on',p.dataset.ap===v));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('on',b.dataset.view===v));$('aViewTitle').textContent=names[v];$('aViewDesc').textContent=descriptions[v];$('crumb').textContent='GP1701 › '+names[v];if(v==='3d'){if(!scene)scene=new window.AmineScene($('aScene'),openDetail);$('aCut').classList.toggle('on',scene.cut);$('aSceneBadge').textContent=scene.cut?'JARAYON KESIMI · gaz ↑ / amin ↓':'TASHQI KO‘RINISH';scene.resize()}if(v==='trends')requestAnimationFrame(drawCharts);render(true)}
showView=function(v){navigate(v)};
root.addEventListener('click',e=>{let g=e.target.closest('[data-go]');if(g)navigate(g.dataset.go);let eq=e.target.closest('[data-eq]');if(eq&&!drag&&!editTags){if(eq.dataset.eq==='sis')navigate('sis');else openDetail(eq.dataset.eq)}let cam=e.target.closest('[data-camera]');if(cam){scene?.setCamera(cam.dataset.camera);root.querySelectorAll('[data-camera]').forEach(b=>b.classList.toggle('on',b===cam))}let fs=e.target.closest('[data-full]');if(fs){const action=document.fullscreenElement?document.exitFullscreen():$(fs.dataset.full).requestFullscreen?.();action?.catch(()=>{$('aViewDesc').textContent='Brauzer to‘liq ekranga ruxsat bermadi. Oddiy ko‘rinish ishlashda davom etadi.'})}});
root.addEventListener('keydown',e=>{if(e.key==='Escape')$('aDrawer').classList.remove('on');if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-eq]')){e.preventDefault();if(e.target.dataset.eq==='sis')navigate('sis');else openDetail(e.target.dataset.eq)}});
$('amPlay').onclick=()=>{if(replay>=0)returnLive();model.running=!model.running;model.event('INFO','RUN',model.running?'Jarayon ishga tushirildi':'Jarayon pauza qilindi');render(true)};
$('amStep').onclick=()=>{if(replay>=0)return;model.singleStep();sampleHistory(true);render(true)};
$('amStop').onclick=()=>{returnLive();model.stop();model.event('INFO','STOP','Simulyatsiya hisobi to‘xtatildi — texnologik ESD emas');render(true)};
$('amReset').onclick=()=>{model.running=false;replay=-1;replayPlaying=false;importTicket++;runtime.accumulator=0;model.reset();model.pause();savedLiveHistory=null;history=[model.snapshot()];lastSample=0;$('aScenario').value='normal';selected=null;$('aDrawer').classList.remove('on');syncInputs();render(true)};
$('aScenario').onchange=e=>{replay=-1;model.setFault(e.target.value);render(true)};$('aSpeed').onchange=e=>speed=+e.target.value;
function syncInputs(){for(let k in model.auto){$('loop-mode-'+k).value=model.auto[k]?'auto':'manual';$('loop-sp-'+k).value=model.sp[k]}for(let v of V)$('av-'+v.id).value=model.command[v.id]}
